import{_ as e,o as t,c as d,ag as o}from"./chunks/framework.C5oN-8Wt.js";const u=JSON.parse('{"title":"相关器","description":"","frontmatter":{},"headers":[],"relativePath":"v0.3.0-alpha/modules/correlator/index.md","filePath":"v0.3.0-alpha/modules/correlator/index.md"}'),r={name:"v0.3.0-alpha/modules/correlator/index.md"};function l(n,a,s,p,c,i){return t(),d("div",null,[...a[0]||(a[0]=[o(`<h1 id="相关器" tabindex="-1">相关器 <a class="header-anchor" href="#相关器" aria-label="Permalink to &quot;相关器&quot;">​</a></h1><p>适用：v0.3.0-alpha · GNU Radio 3.10.12.0<br> 模块类型：<code>correlator</code> · 模块定义版本：1</p><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>在低空观测的教学模型中，可以先保存一段参考数据，再寻找接收数据与它相隔几个样本。相关器将同速的实标量 <code>rx</code> 和 <code>ref</code> 每 N 点分成一个完整窗口，计算所有允许移位下的乘加结果。</p><p>定义为 <code>C[k]=Σ rx[n+k]×ref[n]</code>，其中 <code>k=−(N−1)…+(N−1)</code>，窗外按零参与公式。也就是每移动一格，将对齐的数逐项相乘后相加。正 lag 表示 rx 相对 ref 延迟。采用 full 原始相关，不去均值、不归一化、不除以 N；相关值不是概率或检测置信度。</p><h2 id="典型接线" tabindex="-1">典型接线 <a class="header-anchor" href="#典型接线" aria-label="Permalink to &quot;典型接线&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>同一实标量点表源 ─────────→ ref</span></span>
<span class="line"><span>                 └→ 延时器 → rx</span></span>
<span class="line"><span>                              │</span></span>
<span class="line"><span>                         相关器 correlation</span></span>
<span class="line"><span>                              ├→ 单路 lag 观察器</span></span>
<span class="line"><span>                              └→ 峰值检测器（直接连接）</span></span></code></pre></div><p>两输入必须具有相容的实标量形状及相同实际采样率。<code>correlation</code> 是包含 <code>2N−1</code> 个分量的帧向量，每个分量对应一个 lag；不是复数流，也不是把许多帧拼成的时间波形。</p><p>下表为内置默认参数下的端口。带路数、元素类型或 vlen 的模块会随参数改变流端口。</p><table tabindex="0"><thead><tr><th>方向</th><th>端口</th><th>数据类型</th><th>单位 / 形状</th></tr></thead><tbody><tr><td>输入</td><td><code>rx</code>（接收信号）</td><td><code>numeric_f64</code></td><td>归一化幅度；vlen=1</td></tr><tr><td>输入</td><td><code>ref</code>（参考信号）</td><td><code>numeric_f64</code></td><td>归一化幅度；vlen=1</td></tr><tr><td>输出</td><td><code>correlation</code>（完整相关帧）</td><td><code>numeric_f64</code></td><td>原始相关值；vlen=127</td></tr></tbody></table><p>端口的精确类型和单位见上方目录导出表。两路输入使用实数 Float32，幅度乘加结果按实际输入解释，不把米、秒或相位数据直接当作归一化幅度。</p><h2 id="参数怎么用" tabindex="-1">参数怎么用 <a class="header-anchor" href="#参数怎么用" aria-label="Permalink to &quot;参数怎么用&quot;">​</a></h2><p><code>frame_length</code> 决定每帧需要多少原始样本。较长窗口比较更多数据，也要求参考与延迟副本落在对应完整窗口中；不能只增大 N 就宣称检测能力更强。精确默认、范围和中文标签由真实目录表提供，本页不维护第二份参数表。</p><p>上方端口表按内置默认帧长生成。课例将 N 设为 8 后，相关向量改为 15 个分量，不能把默认端口表的长度照抄到课例。</p><p>内置默认值如下；本机设置可为<strong>新实例</strong>指定其他默认值，打开已有工程保留工程参数。</p><table tabindex="0"><thead><tr><th>参数</th><th>内置默认值</th><th>取值与约束</th><th>修改时机</th></tr></thead><tbody><tr><td>非重叠窗口点数 N<br><code>frame_length</code></td><td><code>64</code></td><td>范围 8 至 512</td><td>重新准备</td></tr></tbody></table><p>有限运行的原始输入配额 Q 必须至少覆盖一帧，并且是 N 的整数倍。否则准备报告节点、Q 和 N，要求调整；不自动改总点数、不补尾、不把半帧当作成功。连续运行只消费完整窗口。</p><p>一个输出 item 是一完整相关帧，item 率为原始 Fs/N，时间为窗口起点。lag 轴记录起点 <code>−(N−1)</code>、步长 1 sample 及真实原始 Fs。尚未确定的原始 Fs 不得当成已知速率；不能用帧率代替它换算延迟。</p><h2 id="在线修改与重新准备" tabindex="-1">在线修改与重新准备 <a class="header-anchor" href="#在线修改与重新准备" aria-label="Permalink to &quot;在线修改与重新准备&quot;">​</a></h2><p>计算参数或结构变化后，先停止，再重新准备和运行。</p><p>本模块不提供在线参数修改。改变计算参数须停止并重新准备；分帧设置影响数据分组，重准备清除旧块状态并使用新的运行时间基准，不能把旧缓存当成新配置结果。</p><h2 id="示例与观察" tabindex="-1">示例与观察 <a class="header-anchor" href="#示例与观察" aria-label="Permalink to &quot;示例与观察&quot;">​</a></h2><h3 id="从相关图手工找出延迟" tabindex="-1">从相关图手工找出延迟 <a class="header-anchor" href="#从相关图手工找出延迟" aria-label="Permalink to &quot;从相关图手工找出延迟&quot;">​</a></h3><p><a href="../../../downloads/v0.3.0-alpha/02-find-delay.cnsproj" download>下载 02-find-delay.cnsproj</a></p><p>来源：PC 本地 GNU Radio 仿真。下载后打开工程，按 F5 运行；本次核验每例参考源运行 64 item，工程不保存样本。</p><p>从相关图手工找出延迟</p><ul><li>Fs=1000 item/s、N=8、Q=64 产生 8 帧；横轴 lag 为 −7…7，唯一绝对峰在 +2，相关值为 +6。</li></ul><h3 id="把延迟换成传播距离" tabindex="-1">把延迟换成传播距离 <a class="header-anchor" href="#把延迟换成传播距离" aria-label="Permalink to &quot;把延迟换成传播距离&quot;">​</a></h3><p><a href="../../../downloads/v0.3.0-alpha/03-delay-to-distance.cnsproj" download>下载 03-delay-to-distance.cnsproj</a></p><p>来源：PC 本地 GNU Radio 仿真。下载后打开工程，按 F5 运行；本次核验每例参考源运行 64 item，工程不保存样本。</p><p>把延迟换成传播距离</p><ul><li>lag=2 → 0.002 s → 0.34 m，采用 340 m/s 往返传播教学模型；仅把延时改为 3 后为 0.51 m。</li></ul><p>教学示例见<a href="./../../learn/02-find-delay/">相关找延迟</a>：N=8、ref=<code>[1,2,1,0,0,0,0,0]</code>、rx=<code>[0,0,1,2,1,0,0,0]</code>。手算 full 相关在 +2 sample 得到唯一绝对峰 +6。该课先从图上读峰，下一课才连接峰值检测器。</p><p>在独立观察器中直接捕获 <code>correlation</code> 的完整父向量，单路选择“相关值—滞后”，显示最新一帧，以 lag/sample 为横轴、相关值为纵轴，并保留真实帧时刻。负 lag 与负相关值都应保留。相关父向量不进入 XY、频谱、瀑布或 I/Q，也不自动为各分量产生频谱。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>全零或常数窗口一定报错吗？</strong> 相关器仍输出真实数学结果。后续峰值检测若没有唯一且高于阈值的绝对峰，含该模块的任务才按相应规则失败。</p><p><strong>公式窗外为零，是否可以少给几个输入点？</strong> 不可以。公式定义的窗外零与运行输入不足不同；模块只处理完整 N 点窗，不补不足的输入。</p><p><strong>峰最高就能证明发现了目标吗？</strong> 不能。周期信号、截断回波及跨窗都可能产生歧义。本批仅提供完整分帧的原始相关，不是通用连续目标检测器。</p><p><a href="./../peak_detector/">峰值检测器</a> · <a href="./../../learn/">学习路径</a></p><h2 id="递进实验" tabindex="-1">递进实验 <a class="header-anchor" href="#递进实验" aria-label="Permalink to &quot;递进实验&quot;">​</a></h2><ul><li><a href="./../../learn/02-find-delay/">11 相关找延迟</a></li><li><a href="./../../learn/03-delay-to-distance/">12 延迟换距离</a></li></ul>`,41)])])}const f=e(r,[["render",l]]);export{u as __pageData,f as default};
